// Fail-closed classification: never equate a successful CI run with production or provider proof.
const payload = $input.first()?.json ?? {};
if (!Array.isArray(payload.workflow_runs)) throw new Error('GITHUB_ACTIONS_SCHEMA_INVALID: workflow_runs missing');
const runs = payload.workflow_runs;
const now = Date.now();
const byWorkflow = new Map();
for (const r of runs) {
  if (!r || !r.name || !r.id || !r.status || !r.created_at) continue;
  const k = String(r.workflow_id ?? r.name);
  const prior = byWorkflow.get(k);
  if (!prior || Date.parse(r.created_at) > Date.parse(prior.created_at) ||
      (Date.parse(r.created_at) === Date.parse(prior.created_at) && Number(r.id) > Number(prior.id))) byWorkflow.set(k, r);
}
const checks = [...byWorkflow.values()].map(r => {
  const started = r.run_started_at ?? r.created_at;
  const age = Math.max(0, Math.floor((now - Date.parse(started)) / 60000));
  return {workflow:r.name,workflow_id:r.workflow_id ?? null,run_id:r.id,sha:r.head_sha ?? null,
    status:r.status,conclusion:r.conclusion ?? null,event:r.event ?? null,
    url:r.html_url ?? null,age_minutes:Number.isFinite(age)?age:null};
});
const failing = checks.filter(r => r.status === 'completed' && !['success','skipped','neutral'].includes(r.conclusion));
const stalled = checks.filter(r => r.status !== 'completed' && r.age_minutes !== null && r.age_minutes > 45);
const pending = checks.filter(r => r.status !== 'completed');
const missing = checks.length === 0;
const next = failing.length ? 'READ_FAILED_JOB_LOGS_AND_REPAIR' : stalled.length ? 'INVESTIGATE_STALLED_JOB' :
  missing ? 'CHECK_GITHUB_API_AND_PAGINATION' : pending.length ? 'RECHECK_IN_PROGRESS' :
  'VERIFY_COUNCIL_PROVIDERS_ARTIFACT_RUNTIME_AND_SHA';
const status = failing.length || stalled.length ? 'FAIL' : pending.length ? 'RUNNING' : 'NOT_VERIFIED';
return [{json:{schema_version:2,observed_at:new Date(now).toISOString(),repository:'psw2025-cmd/Genesis_System3',
  lane:'LEGACY_ONLY',status,next_action:next,failures:failing,stalled,pending,checks,
  observed_latest_workflows:checks.length,verified_workflow_count:checks.filter(r=>r.status==='completed'&&r.conclusion==='success').length,
  incomplete_coverage:runs.length>=100,provider_review_verified:false,artifact_readback_verified:false,
  runtime_verified:false,live_trading_allowed:false,
  latency_minutes:Math.max(0,...checks.map(r=>r.age_minutes??0))}}];
